import DOMRect from '../dom/DOMRect.js';
import Element from '../nodes/element/Element.js';
import IntersectionObserverEntry from './IntersectionObserverEntry.js';
import type IIntersectionObserverInit from './IIntersectionObserverInit.js';
import type BrowserWindow from '../window/BrowserWindow.js';

interface IRootMargin {
	value: number;
	unit: 'px' | '%';
	text: string;
}

interface IObservation {
	ratio: number;
	isIntersecting: boolean;
}

/**
 * The IntersectionObserver interface of the Intersection Observer API provides a way to asynchronously observe changes in the intersection of a target element with an ancestor element or with a top-level document's viewport.
 *
 * @see https://developer.mozilla.org/en-US/docs/Web/API/IntersectionObserver
 */
export default class IntersectionObserver {
	#callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void;
	#observations = new Map<Element, IObservation | null>();
	#records: IntersectionObserverEntry[] = [];
	#deliveryQueued = false;
	#deliveryGeneration = 0;
	#rootMargins: IRootMargin[];
	#window: BrowserWindow | null = null;
	#onGeometryChange = (): void => {
		this.#check();
		this.#queueDelivery(this.#window?.queueMicrotask.bind(this.#window));
	};

	/** The element used as the intersection root, or the viewport. */
	public readonly root: Element | null;
	/** The normalized root margin. */
	public readonly rootMargin: string;
	/** The normalized threshold values. */
	public readonly thresholds: number[];

	/**
	 * Constructor.
	 *
	 * @param callback Callback.
	 * @param options Options.
	 */
	constructor(
		callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void,
		options?: IIntersectionObserverInit
	) {
		if (typeof callback !== 'function') {
			throw new TypeError('IntersectionObserver callback must be a function.');
		}

		const init = options || {};
		if (init.root !== undefined && init.root !== null && !(init.root instanceof Element)) {
			throw new TypeError('IntersectionObserver root must be an Element or null.');
		}

		this.#callback = callback;
		this.root = init.root || null;
		this.#rootMargins = this.#parseRootMargin(init.rootMargin);
		this.rootMargin = this.#rootMargins.map((margin) => margin.text).join(' ');
		this.thresholds = this.#parseThresholds(init.threshold);
	}

	/**
	 * Starts observing.
	 *
	 * @param _target Target.
	 */
	public observe(target: Element): void {
		if (!(target instanceof Element)) {
			throw new TypeError('IntersectionObserver target must be an Element.');
		}

		if (!this.#observations.has(target)) {
			this.#observations.set(target, null);
			this.#listen(target.ownerDocument.defaultView);
		}

		this.#check();
		this.#queueDelivery(
			target.ownerDocument.defaultView?.queueMicrotask.bind(target.ownerDocument.defaultView)
		);
	}

	/**
	 * Disconnects.
	 */
	public disconnect(): void {
		this.#observations.clear();
		this.#records = [];
		this.#deliveryGeneration++;
		this.#deliveryQueued = false;
		this.#stopListening();
	}

	/**
	 * Unobserves an element.
	 *
	 * @param _target Target.
	 */
	public unobserve(target: Element): void {
		this.#observations.delete(target);
		this.#records = this.#records.filter((entry) => entry.target !== target);
		if (!this.#observations.size) {
			this.#stopListening();
		}
	}

	/**
	 * Returns an array of IntersectionObserverEntry objects for all observed targets.
	 *
	 * @returns Records.
	 */
	public takeRecords(): IntersectionObserverEntry[] {
		const records = this.#records;
		this.#records = [];
		return records;
	}

	/** Queues asynchronous callback delivery for the current records. */
	#queueDelivery(queueMicrotask: ((callback: () => void) => void) | undefined): void {
		if (this.#deliveryQueued) {
			return;
		}
		this.#deliveryQueued = true;
		const generation = this.#deliveryGeneration;
		const deliver = () => {
			if (generation !== this.#deliveryGeneration) {
				return;
			}
			this.#deliveryQueued = false;
			const records = this.takeRecords();
			if (records.length) {
				this.#callback(records, this);
			}
		};
		if (queueMicrotask) {
			queueMicrotask(deliver);
		} else {
			globalThis.queueMicrotask(deliver);
		}
	}

	/** Calculates entries in target observation order. */
	#check(): void {
		for (const [target, previous] of this.#observations) {
			const entry = this.#createEntry(target);
			const current = { ratio: entry.intersectionRatio, isIntersecting: entry.isIntersecting };
			if (
				previous === null ||
				previous.isIntersecting !== current.isIntersecting ||
				this.thresholds.some(
